"""Build review documents from the editable shot JSON; no separate storyboard database."""
from pathlib import Path
import json, html
from PIL import Image, ImageDraw, ImageFont

root=Path('assets/milestone8')
b=json.loads((root/'storyboard.json').read_text(encoding='utf-8'))
e=html.escape
def tc(ms):
    return f'{ms//60000:02}:{ms//1000%60:02}.{ms%1000:03}'
lines=['# The whole story — timecoded storyboard','',
       'ESTABLISHED CANON: [The world made of theories](../../docs/WORLD_MADE_OF_THEORIES.md). All cuts and blocking below are PROPOSED SHOT DIRECTION, pending Leo’s review.',
       '', 'Master: 262.8 seconds, 1920×1080, 30 fps, 7,884 frames. Millisecond authoring; events appear on ceil(ms × 30 / 1000). No soundtrack alteration.',
       '', 'Source of truth: [storyboard.json](storyboard.json). Gallery and this document are generated from it. [Asset status](ASSETS.md).','']
cards=[]
for s in b['shots']:
    duration=(s['endMs']-s['startMs'])/1000
    lyrics='; '.join(f'{a["id"]} — {a["text"]} (vocal {tc(a["startMs"])}; display {tc(a["presentation"]["startMs"])})' for a in s['lyricAnchors']) or 'Instrumental / held visual; no active phrase.'
    music='; '.join(f'{a["id"]}: {tc(a["peakMs"])} ({a["action"]}; {"enabled" if a["enabled"] else "held candidate"})' for a in s['musicalAnchors']) or 'No selected cue; master remains continuous.'
    lines += [f'## {s["id"]} · {s["sequenceId"]} · {tc(s["startMs"])}–{tc(s["endMs"])} · {s["title"]}', '',f'![{s["title"]}](review-v2/{s["id"]}.jpg)','',f'**A-roll / character:** {s["aRoll"]}',f'\n**B-roll / background:** {s["bRoll"]}',f'\n**Camera:** {s["camera"]}',f'\n**Layers:** {" → ".join(s["layers"])}',f'\n**Occlusion:** {s["occlusion"]}',f'\n**Captions:** {s["captionLayout"]}; story protection {s["protectedRegions"]}. Approved timing unchanged.',f'\n**Lyric anchors:** {lyrics}',f'\n**Music anchors:** {music}',f'\n**Assets:** reusable {", ".join(s["reusableAssets"])}; missing finished art {", ".join(s["missingAssets"]) or "none required for rough blocking"}.',f'\n**Evidence:** {s["historicalStatus"]}',f'\n**Approval:** {s["creativeStatus"]}',f'\n**Dependencies / complexity:** {", ".join(s["dependencies"])} / {s["complexity"]}.',f'\n[Play interval](review-v2/full.mp4#t={s["startMs"]/1000},{s["endMs"]/1000})','']
    cards.append(f'''<article id="{s['id']}"><a href="full.mp4#t={s['startMs']/1000},{s['endMs']/1000}" class="seek" data-start="{s['startMs']/1000}" data-end="{s['endMs']/1000}"><img loading="lazy" src="{s['id']}.jpg" alt="{e(s['title'])}"></a><div class="body"><small>{s['id']} / {s['sequenceId']} · {tc(s['startMs'])}–{tc(s['endMs'])} · {duration:g}s</small><h2>{e(s['title'])}</h2><p>{e(s['aRoll'])}</p><p class="muted">B-roll: {e(s['bRoll'])}</p><details><summary>Direction, anchors & evidence</summary><p>{e(s['camera'])}</p><p>{e(s['occlusion'])}</p><p>{e(lyrics)}</p><p>{e(music)}</p><p>{e(s['historicalStatus'])}</p><p>Missing finished art: {e(', '.join(s['missingAssets']) or 'none for rough staging')}</p></details><button data-start="{s['startMs']/1000}" data-end="{s['endMs']/1000}">Play this interval</button></div></article>''')
lines += ['## SH053 · S16 · Post-song — unplaced','',b['postSong']['aRoll'], '',b['postSong']['bRoll'],'',b['postSong']['audio'],'','Not included in the master. Duration and audio require a separate editorial decision.']
(root/'STORYBOARD.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Swarm Song · The whole story</title><style>
*{box-sizing:border-box}body{margin:0;background:#efe6d4;color:#3d463e;font:17px/1.55 system-ui}header,main{max-width:1400px;margin:auto;padding:28px}h1{font:700 clamp(32px,5vw,58px)/1.1 Georgia;margin:12px 0}h2{font:700 23px Georgia;margin:12px 0}small,.muted{color:#6c6a5d}a{color:#326e76}video{width:100%;background:#111;border:7px solid #fff7e7;border-radius:5px}.intro{max-width:900px}.players{display:grid;grid-template-columns:1.4fr 1fr;gap:24px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}article{background:#fff9eb;box-shadow:3px 5px 0 #c5bda74a;scroll-margin-top:15px}article img{width:100%;display:block}.body{padding:20px}button{background:#386f70;color:white;border:0;padding:10px 17px;border-radius:4px;font:inherit;cursor:pointer}details{font-size:14px;margin-bottom:15px}summary{cursor:pointer}nav{display:flex;gap:18px;flex-wrap:wrap}section{margin:32px 0}.notice{border-left:4px solid #ba8c4a;padding-left:18px}@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}.players{grid-template-columns:1fr}}@media(max-width:550px){.grid{grid-template-columns:1fr}}</style>
<header><small>SWARM SONG · MILESTONE 8 · DEVELOPMENT ANIMATIC</small><h1>The whole story,<br>one frame at a time.</h1><p class="intro">52 proposed shots across the unaltered 262.8-second master. Approved bunny sprites, paper scenery and V6 captions meet deliberately rough fantasy cutouts. Canon is established; this new blocking awaits Leo’s direction.</p><nav><a href="../STORYBOARD.md">Storyboard</a><a href="../storyboard.json">Editable JSON</a><a href="../ASSETS.md">Asset plan</a><a href="../REVIEW.md">Review & limits</a><a href="../README.md">Reproduce</a></nav></header><main><section class="players"><div><h2>The complete song</h2><video id="full" controls preload="metadata" src="full.mp4"></video><p id="interval">Full master · 00:00–04:22.800</p></div><div><h2>The theory becomes a world</h2><video controls preload="metadata" src="middle.mp4"></video><p>Focused middle act · 01:23–01:52 · 29 seconds</p><p class="notice">The castle is a new proposed paper asset matching Leo’s reference. The shrug, costume and RPG props remain rough blocking. Continuous audiovisual approval belongs to the director; see the review report for what was actually inspected.</p></div></section><h2>The editable cut list</h2><p>Select any card to seek the full film and stop at that shot’s end. The master continues across shot boundaries during normal playback.</p><section class="grid">CARDS</section><section class="notice"><h2>After the song — not yet timed</h2><p>Cast wave · AND YOU · “see you around!” · optional verified QR. Separate duration/audio decision required; deliberately outside the 262.8-second film.</p></section></main><script>const v=document.querySelector('#full');let stop=null;document.querySelectorAll('[data-start]').forEach(el=>el.onclick=ev=>{ev.preventDefault();stop=+el.dataset.end;v.currentTime=+el.dataset.start;document.querySelector('#interval').textContent=`Selected interval: ${el.dataset.start}–${el.dataset.end}s`;v.scrollIntoView({behavior:'smooth',block:'center'});v.play();});v.addEventListener('timeupdate',()=>{if(stop!==null&&v.currentTime>=stop){v.pause();stop=null;document.querySelector('#interval').textContent='Resume to continue through the master';}});</script></html>'''
(root/'review-v2/index.html').write_text(page.replace('CARDS',''.join(cards)),encoding='utf-8')
font=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',19)
for page,start in enumerate(range(0,len(b['shots']),12),1):
    subset=b['shots'][start:start+12];sheet=Image.new('RGB',(1440,4*310),(240,231,213));d=ImageDraw.Draw(sheet)
    for i,s in enumerate(subset):
        im=Image.open(root/'review-v2'/f'{s["id"]}.jpg').convert('RGB');im.thumbnail((472,266));x=i%3*480;y=i//3*310;sheet.paste(im,(x,y));d.text((x+6,y+270),f'{s["id"]} {tc(s["startMs"])}  {s["title"][:28]}',font=font,fill='#453c30')
    sheet.save(root/'review-v2'/f'contact-{page}.jpg',quality=90)
print('Storyboard, gallery and contact sheets generated.')
